/* Black-box model of tsl::hopscotch_map arithmetic as exercised by test11.cpp
 *
 * Hypothesis under test (all f32 where the C++ lib uses float):
 *   bucket_count starts at 0
 *   load_threshold = (size_t)((float)bucket_count * max_load_factor)   // truncating cast
 *   before inserting each NEW element: if (size >= load_threshold) grow
 *   grow: bucket_count = (bucket_count == 0 ? 2 : bucket_count * 2)  [ (mask+1)*2 ]
 *   load_factor() = bucket_count == 0 ? 0.0f : (float)size / (float)bucket_count
 *   max_load_factor(0.5f) -> recompute threshold
 *   rehash(0) -> bucket_count = round_up_pow2( (size_t)ceilf((float)size / mlf) ), 0 stays 0
 *   printing: std::cout << float  ==  printf("%g", (double)f)
 */
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stddef.h>

static size_t round_up_pow2(size_t v) {
    if (v == 0) return 0;          /* tsl: min_bucket_count_in_out == 0 -> mask stays 0 */
    size_t p = 1;
    while (p < v) p <<= 1;
    return p;
}

static size_t threshold_of(size_t bucket_count, float mlf) {
    /* float(bucket_count) * mlf, truncated to size_t */
    return (size_t)((float)bucket_count * mlf);
}

static float load_factor_of(size_t size, size_t bucket_count) {
    if (bucket_count == 0) return 0.0f;
    return (float)size / (float)bucket_count;
}

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: model N\n"); return 2; }
    long count = strtol(argv[1], NULL, 10);

    float mlf = 0.9f;              /* default max_load_factor */
    size_t bucket_count = 0;
    size_t size = 0;
    size_t thr = threshold_of(bucket_count, mlf);

    for (long i = 0; i < count; i++) {
        /* keys 0..count-1 are all distinct -> every insert is a NEW element */
        if (size >= thr) {
            bucket_count = (bucket_count == 0) ? 2 : bucket_count * 2;
            thr = threshold_of(bucket_count, mlf);
        }
        size++;
    }

    float lf1 = load_factor_of(size, bucket_count);

    /* map.max_load_factor(0.5) */
    mlf = 0.5f;
    thr = threshold_of(bucket_count, mlf);

    /* map.rehash(0) */
    {
        size_t want = (size_t)ceilf((float)size / mlf);   /* max(0, ceil(size/mlf)) */
        bucket_count = round_up_pow2(want);
        thr = threshold_of(bucket_count, mlf);
    }
    (void)thr;

    float lf2 = load_factor_of(size, bucket_count);

    printf("%g %g\n", (double)lf1, (double)lf2);
    return 0;
}

/* Emits the growth-boundary table: bucket_count -> load_threshold, for the
 * default max_load_factor 0.9f and for 0.5f.
 * threshold = (size_t)((float)bucket_count * mlf)   -- truncating cast
 */
#include <stdio.h>
#include <stddef.h>

int main(void) {
    printf("bucket_count\tthr_mlf0.9\tthr_mlf0.5\n");
    printf("%zu\t%zu\t%zu\n", (size_t)0,
           (size_t)((float)0 * 0.9f), (size_t)((float)0 * 0.5f));
    for (size_t bc = 2; bc <= ((size_t)1 << 24); bc <<= 1) {
        size_t t9 = (size_t)((float)bc * 0.9f);
        size_t t5 = (size_t)((float)bc * 0.5f);
        printf("%zu\t%zu\t%zu\n", bc, t9, t5);
    }
    return 0;
}

/* Generates the sampled count set for the sweep, one per line, sorted+unique. */
#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>

#define MAXN 4000000
static long long v[MAXN];
static int n = 0;
static long long LIMIT;

static void add(long long x) {
    if (x < 0 || x > LIMIT) return;
    if (n < MAXN) v[n++] = x;
}

static int cmpll(const void *a, const void *b) {
    long long x = *(const long long *)a, y = *(const long long *)b;
    return (x > y) - (x < y);
}

int main(int argc, char **argv) {
    LIMIT = (argc > 1) ? atoll(argv[1]) : 4194305LL;

    /* powers of two +/- 1 (and the power itself) */
    for (int k = 0; k <= 25; k++) {
        long long p = 1LL << k;
        add(p - 1); add(p); add(p + 1);
    }

    /* growth boundaries: thr = (size_t)((float)bc * 0.9f) for bc = 2,4,...,2^25 */
    for (int k = 1; k <= 25; k++) {
        size_t bc = (size_t)1 << k;
        long long thr = (long long)(size_t)((float)bc * 0.9f);
        add(thr - 2); add(thr - 1); add(thr); add(thr + 1); add(thr + 2);
    }

    /* rehash(0) boundaries with mlf=0.5: ceil(2n) crossing a power of two */
    for (int k = 1; k <= 25; k++) {
        long long half = (1LL << k) / 2;
        add(half - 1); add(half); add(half + 1);
    }

    /* explicit interesting values */
    add(10000); add(100000); add(1000000); add(4194304);
    add(9999); add(10001); add(99999); add(100001);
    add(999999); add(1000001);

    /* pseudo-random spread */
    unsigned long long s = 88172645463325252ULL;
    for (int i = 0; i < 3000; i++) {
        s ^= s << 13; s ^= s >> 7; s ^= s << 17;
        add((long long)(s % 4194305ULL));
    }

    qsort(v, n, sizeof(long long), cmpll);
    long long prev = -1;
    for (int i = 0; i < n; i++) {
        if (v[i] == prev) continue;
        prev = v[i];
        printf("%lld\n", v[i]);
    }
    return 0;
}

/* Black-box model of tsl::hopscotch_map arithmetic as exercised by test11.cpp
 *
 * Hypothesis under test (all f32 where the C++ lib uses float):
 *   bucket_count starts at 0; size counts distinct keys (0..count-1 all distinct)
 *   load_threshold = (size_t)((float)bucket_count * max_load_factor)   // truncating cast
 *   before inserting each NEW element: if (size >= load_threshold) grow
 *   grow: bucket_count = (bucket_count == 0 ? 2 : bucket_count * 2)   [ (mask+1)*2 ]
 *   load_factor() = bucket_count == 0 ? 0.0f : (float)size / (float)bucket_count
 *   max_load_factor(0.5f) -> recompute threshold
 *   rehash(0) -> bucket_count = round_up_pow2( (size_t)ceilf((float)size / mlf) ); 0 stays 0
 *   printing: std::cout << float  ==  printf("%g", (double)f)
 *
 * usage: model N [--slow]
 *        model --selfcheck LO HI     (fast path vs literal per-element loop)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stddef.h>

#define DEFAULT_MLF 0.9f

static size_t round_up_pow2(size_t v) {
    if (v == 0) return 0;          /* tsl: min_bucket_count_in_out == 0 -> mask stays 0 */
    size_t p = 1;
    while (p < v) p <<= 1;
    return p;
}

static size_t threshold_of(size_t bucket_count, float mlf) {
    return (size_t)((float)bucket_count * mlf);   /* truncating cast */
}

static float load_factor_of(size_t size, size_t bucket_count) {
    if (bucket_count == 0) return 0.0f;
    return (float)size / (float)bucket_count;
}

/* literal per-element simulation */
static size_t bc_after_inserts_slow(size_t count) {
    size_t bc = 0, size = 0, thr = threshold_of(0, DEFAULT_MLF);
    for (size_t i = 0; i < count; i++) {
        if (size >= thr) {
            bc = (bc == 0) ? 2 : bc * 2;
            thr = threshold_of(bc, DEFAULT_MLF);
        }
        size++;
    }
    return bc;
}

/* closed-form equivalent: jump straight to the next growth trigger */
static size_t bc_after_inserts_fast(size_t count) {
    size_t bc = 0, size = 0, thr = threshold_of(0, DEFAULT_MLF);
    while (size < count) {
        if (size >= thr) {
            bc = (bc == 0) ? 2 : bc * 2;
            thr = threshold_of(bc, DEFAULT_MLF);
        } else {
            size = (count < thr) ? count : thr;
        }
    }
    return bc;
}

static void emit(size_t count, size_t bc_after) {
    size_t size = count;
    size_t bc = bc_after;

    float lf1 = load_factor_of(size, bc);

    /* map.max_load_factor(0.5) */
    float mlf = 0.5f;
    (void)threshold_of(bc, mlf);

    /* map.rehash(0):  count_ = max(0, (size_type)ceil(float(size)/mlf)) */
    size_t want = (size_t)ceilf((float)size / mlf);
    bc = round_up_pow2(want);
    (void)threshold_of(bc, mlf);

    float lf2 = load_factor_of(size, bc);

    printf("%g %g\n", (double)lf1, (double)lf2);
}

int main(int argc, char **argv) {
    if (argc >= 2 && strcmp(argv[1], "--selfcheck") == 0) {
        size_t lo = strtoull(argv[2], NULL, 10), hi = strtoull(argv[3], NULL, 10);
        size_t bad = 0;
        for (size_t n = lo; n <= hi; n++) {
            size_t a = bc_after_inserts_slow(n), b = bc_after_inserts_fast(n);
            if (a != b) { bad++; printf("SELFCHECK MISMATCH n=%zu slow=%zu fast=%zu\n", n, a, b); }
        }
        printf("selfcheck range [%zu,%zu] mismatches=%zu\n", lo, hi, bad);
        return bad != 0;
    }
    if (argc < 2) { fprintf(stderr, "usage: model N [--slow]\n"); return 2; }
    size_t count = strtoull(argv[1], NULL, 10);
    int slow = (argc >= 3 && strcmp(argv[2], "--slow") == 0);
    emit(count, slow ? bc_after_inserts_slow(count) : bc_after_inserts_fast(count));
    return 0;
}

/* Variant models: probe which parts of the hypothesis are load-bearing.
 * usage: variants VARIANT N
 * Variants:
 *   base    : the hypothesis as stated
 *   thr_d   : threshold multiply in double instead of float
 *   mlf_d   : default mlf is double 0.9 (not 0.9f)
 *   gt      : growth test uses  size > thr  instead of  size >= thr
 *   grow1   : first growth goes 0 -> 1 instead of 0 -> 2
 *   rup0is1 : round_up_pow2(0) == 1 instead of 0
 *   rupgt   : rehash rounds to strictly-greater power of two
 *   rfloor  : rehash uses floor instead of ceil
 *   rdouble : rehash division/ceil done in double
 *   lfdouble: load_factor computed in double then narrowed to float
 *   thrceil : threshold uses ceil instead of truncation
 *   nospecial0 : load_factor does NOT special-case bucket_count==0 (0/0 -> nan)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stddef.h>

static const char *V;
static int is(const char *s) { return strcmp(V, s) == 0; }

static size_t round_up_pow2(size_t v) {
    if (v == 0) return is("rup0is1") ? 1 : 0;
    size_t p = 1;
    while (p < v) p <<= 1;
    if (is("rupgt") && p == v) p <<= 1;
    return p;
}

static double default_mlf_d(void) { return is("mlf_d") ? 0.9 : (double)0.9f; }

static size_t threshold_default(size_t bc) {
    if (is("thr_d") || is("mlf_d")) return (size_t)((double)bc * default_mlf_d());
    if (is("thrceil")) return (size_t)ceilf((float)bc * 0.9f);
    return (size_t)((float)bc * 0.9f);
}

static float load_factor_of(size_t size, size_t bc) {
    if (bc == 0 && !is("nospecial0")) return 0.0f;
    if (is("lfdouble")) return (float)((double)size / (double)bc);
    return (float)size / (float)bc;
}

int main(int argc, char **argv) {
    if (argc < 3) { fprintf(stderr, "usage: variants VARIANT N\n"); return 2; }
    V = argv[1];
    size_t count = strtoull(argv[2], NULL, 10);

    size_t bc = 0, size = 0, thr = threshold_default(0);
    while (size < count) {
        int grow = is("gt") ? (size > thr) : (size >= thr);
        if (grow) {
            bc = (bc == 0) ? (is("grow1") ? 1 : 2) : bc * 2;
            thr = threshold_default(bc);
        } else {
            if (thr <= size) { /* would never advance: emulate literal loop one step */
                size++;
            } else {
                size = (count < thr) ? count : thr;
            }
        }
    }
    float lf1 = load_factor_of(size, bc);

    /* max_load_factor(0.5); rehash(0) */
    size_t want;
    if (is("rdouble"))      want = (size_t)ceil((double)size / 0.5);
    else if (is("rfloor"))  want = (size_t)floorf((float)size / 0.5f);
    else                    want = (size_t)ceilf((float)size / 0.5f);
    bc = round_up_pow2(want);
    float lf2 = load_factor_of(size, bc);

    printf("%g %g\n", (double)lf1, (double)lf2);
    return 0;
}

