/* Searches for counts where load_factor computed as f32 prints differently from
 * the same ratio computed/kept as f64.  Also verifies the algebraic claim that
 * (float)((double)n/(double)bc) == (float)n/(float)bc for power-of-two bc.
 *
 * usage: findprec LO HI
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stddef.h>

static size_t thr_of(size_t bc) { return (size_t)((float)bc * 0.9f); }

static size_t round_up_pow2(size_t v) {
    if (v == 0) return 0;
    size_t p = 1; while (p < v) p <<= 1; return p;
}

int main(int argc, char **argv) {
    size_t lo = strtoull(argv[1], NULL, 10), hi = strtoull(argv[2], NULL, 10);

    /* advance the growth model up to lo */
    size_t bc = 0, thr = thr_of(0), size = 0;
    while (size < lo) {
        if (size >= thr) { bc = bc ? bc * 2 : 2; thr = thr_of(bc); }
        else size = (lo < thr) ? lo : thr;
    }

    long long narrow_diffs = 0, print_diffs = 0, shrinks = 0;
    char b1[64], b2[64];

    for (size_t n = lo; n <= hi; n++) {
        if (n > 0) { /* growth check for inserting element #n */
            if (size >= thr) { bc = bc ? bc * 2 : 2; thr = thr_of(bc); }
            size = n;
        }

        /* --- claim: narrowing a double ratio to float == float ratio --- */
        float f32path = (float)n / (float)bc;
        float f64narrowed = (float)((double)n / (double)bc);
        if (memcmp(&f32path, &f64narrowed, sizeof(float)) != 0) {
            if (narrow_diffs++ < 5)
                printf("NARROW-DIFF n=%zu bc=%zu f32=%.17g f64narrowed=%.17g\n",
                       n, bc, (double)f32path, (double)f64narrowed);
        }

        /* --- printed output: f32 value vs unnarrowed f64 value --- */
        double d_f32 = (double)f32path;
        double d_f64 = (double)n / (double)bc;
        if (d_f32 != d_f64) {
            snprintf(b1, sizeof b1, "%g", d_f32);
            snprintf(b2, sizeof b2, "%g", d_f64);
            if (strcmp(b1, b2) != 0) {
                if (print_diffs++ < 20)
                    printf("PRINT-DIFF lf1 n=%zu bc=%zu f32=[%s] f64=[%s]\n", n, bc, b1, b2);
                else print_diffs++;
            }
        }

        /* --- rehash(0) with mlf=0.5: does it ever shrink? --- */
        size_t bc2 = round_up_pow2((size_t)ceilf((float)n / 0.5f));
        if (bc2 < bc) { if (shrinks++ < 5) printf("SHRINK n=%zu bc_before=%zu bc_after=%zu\n", n, bc, bc2); }

        /* printed output for lf2 as well */
        float g32 = bc2 ? (float)n / (float)bc2 : 0.0f;
        double dg32 = (double)g32, dg64 = bc2 ? (double)n / (double)bc2 : 0.0;
        if (dg32 != dg64) {
            snprintf(b1, sizeof b1, "%g", dg32);
            snprintf(b2, sizeof b2, "%g", dg64);
            if (strcmp(b1, b2) != 0) {
                if (print_diffs++ < 20)
                    printf("PRINT-DIFF lf2 n=%zu bc2=%zu f32=[%s] f64=[%s]\n", n, bc2, b1, b2);
            }
        }
    }
    printf("range [%zu,%zu]: narrow_diffs=%lld print_diffs=%lld shrinks=%lld\n",
           lo, hi, narrow_diffs, print_diffs, shrinks);
    return 0;
}
